// StudentRegister.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

import { authHeaders } from "../auth";

await fetch("/api/register-student", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    ...authHeaders(),  // this adds Authorization: Bearer <token>
  },
  body: JSON.stringify(studentData),
});

export default function StudentRegister() {
  const [name, setName] = useState("");
  const [overallScore, setOverallScore] = useState("");
  const [careerInterests, setCareerInterests] = useState("");
  const [address, setAddress] = useState("");
  const [courseScores, setCourseScores] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("Mathematics");
  const [score, setScore] = useState(0);
  const navigate = useNavigate();

  const handleAddCourse = () => {
    if (score < 0 || score > 100) {
      toast.error("Score must be between 0 and 100");
      return;
    }
    setCourseScores([...courseScores, { course: selectedCourse, score }]);
  };

  const handleSubmit = async () => {
    const payload = {
      name,
      overall_score: overallScore,
      career_interests: careerInterests,
      address,
      course_scores: Object.fromEntries(courseScores.map(cs => [cs.course, cs.score]))
    };
    // Send to backend API (assume /api/register-student)
    try {
      const res = await fetch("/api/register-student", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error("Failed to register student");
      toast.success("Registration successful!");
      navigate("/student/dashboard");
    } catch (err) {
      toast.error(err.message);
    }
  };

  return (
    <div className="max-w-2xl mx-auto mt-10 p-6 bg-slate-800 rounded-xl shadow-xl">
      <h2 className="text-3xl font-semibold mb-4">Student Registration</h2>
      <input type="text" placeholder="Name" className="input" value={name} onChange={(e) => setName(e.target.value)} />
      <input type="number" placeholder="Overall GPA" className="input" value={overallScore} onChange={(e) => setOverallScore(e.target.value)} />
      <input type="text" placeholder="Career Interests" className="input" value={careerInterests} onChange={(e) => setCareerInterests(e.target.value)} />
      <input type="text" placeholder="Address" className="input" value={address} onChange={(e) => setAddress(e.target.value)} />

      <div className="my-4">
        <h3 className="font-semibold">Course Scores</h3>
        <select className="input" value={selectedCourse} onChange={(e) => setSelectedCourse(e.target.value)}>
          {['Mathematics','Science','English','History','Programming','Art','Music'].map(c => (
            <option key={c}>{c}</option>
          ))}
        </select>
        <input type="number" placeholder="Score" className="input" value={score} onChange={(e) => setScore(Number(e.target.value))} />
        <button onClick={handleAddCourse} className="btn">Add Course</button>
        <ul className="list-disc ml-6 mt-2">
          {courseScores.map((cs, idx) => (
            <li key={idx}>{cs.course}: {cs.score}</li>
          ))}
        </ul>
      </div>
      <button onClick={handleSubmit} className="btn bg-green-500 hover:bg-green-600">Register</button>
    </div>
  );
}
